"""SQLite adapter that runs SAP HANA-dialect SQL.

Only the HANA constructs we actually use are translated. When you write HANA SQL
that SQLite rejects, add a rule to `_TRANSLATIONS` (or a function in `_register_functions`).
"""

import re
import sqlite3
from pathlib import Path

from app.db.base import Params, Row

_TRANSLATIONS: list[tuple[re.Pattern[str], str]] = [
    # CREATE COLUMN TABLE / CREATE ROW TABLE -> CREATE TABLE
    (re.compile(r"\bCREATE\s+(?:COLUMN|ROW)\s+TABLE\b", re.I), "CREATE TABLE"),
    # BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY -> INTEGER PRIMARY KEY AUTOINCREMENT
    (
        re.compile(
            r"\b(?:BIGINT|INTEGER|INT)\s+GENERATED\s+(?:BY\s+DEFAULT|ALWAYS)\s+AS\s+IDENTITY"
            r"(?:\s*\([^)]*\))?\s+PRIMARY\s+KEY\b",
            re.I,
        ),
        "INTEGER PRIMARY KEY AUTOINCREMENT",
    ),
    # SQLite's CURRENT_TIMESTAMP is already UTC
    (re.compile(r"\bCURRENT_UTCTIMESTAMP\b", re.I), "CURRENT_TIMESTAMP"),
    (re.compile(r"\bCURRENT_UTCDATE\b", re.I), "CURRENT_DATE"),
]


def translate(sql: str) -> str:
    for pattern, replacement in _TRANSLATIONS:
        sql = pattern.sub(replacement, sql)
    return sql


def _register_functions(conn: sqlite3.Connection) -> None:
    # HANA's single-row DUMMY table, e.g. `SELECT CURRENT_TIMESTAMP FROM DUMMY`
    conn.execute("CREATE TEMP VIEW IF NOT EXISTS DUMMY AS SELECT 'X' AS DUMMY")


class SQLiteConnection:
    dialect = "sqlite"

    def __init__(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        self._conn = sqlite3.connect(path)
        self._conn.execute("PRAGMA foreign_keys = ON")
        _register_functions(self._conn)

    def _run(self, sql: str, params: Params) -> sqlite3.Cursor:
        return self._conn.execute(translate(sql), tuple(params))

    @staticmethod
    def _rows(cursor: sqlite3.Cursor, rows: list[tuple]) -> list[Row]:
        names = [d[0].lower() for d in cursor.description or ()]
        return [dict(zip(names, row, strict=True)) for row in rows]

    def fetch_all(self, sql: str, params: Params = ()) -> list[Row]:
        cursor = self._run(sql, params)
        return self._rows(cursor, cursor.fetchall())

    def fetch_one(self, sql: str, params: Params = ()) -> Row | None:
        cursor = self._run(sql, params)
        row = cursor.fetchone()
        return self._rows(cursor, [row])[0] if row else None

    def execute(self, sql: str, params: Params = ()) -> int:
        return self._run(sql, params).rowcount

    def insert(self, sql: str, params: Params = ()) -> int:
        cursor = self._run(sql, params)
        assert cursor.lastrowid is not None
        return cursor.lastrowid

    def table_exists(self, name: str) -> bool:
        row = self._conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND upper(name) = upper(?)", (name,)
        ).fetchone()
        return row is not None

    def commit(self) -> None:
        self._conn.commit()

    def rollback(self) -> None:
        self._conn.rollback()

    def close(self) -> None:
        self._conn.close()


class SQLiteDatabase:
    def __init__(self, path: Path) -> None:
        self.path = path

    def connect(self) -> SQLiteConnection:
        return SQLiteConnection(self.path)

    def ping(self) -> bool:
        conn = self.connect()
        try:
            return conn.fetch_one("SELECT 1 AS ok FROM DUMMY") is not None
        finally:
            conn.close()
